export interface Customer {
  id: number
  email: string
  fullName: string
  phone?: string
  shippingAddress: Address
  createdAt: Date
}

export interface Address {
  street: string
  city: string
  postalCode: string
  country: string
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
  Cancelled = 'cancelled',
}

export interface Order {
  id: number
  customer: Customer
  status: OrderStatus
  lines: OrderLine[]
  couponCode: string | null
  tags: string[]
  placedAt: Date
}

export interface OrderLine {
  product: Product
  quantity: number
  unitPrice: number
}

export interface Product {
  id: number
  sku: string
  name: string
  price: number
  categories: Category[]
  attributes: Record<string, string>
}

export interface Category {
  id: number
  name: string
  products: Product[]
}
